input.content:
{"seg": "QASHANI:1:1", "konu": "اسم: isim ve Allah'ın isimleri", "tur": "isari", "alim": "el-Kâşânî", "alinti": "اسم الشيء ما يعرف به، فأسماء الله تعالى هي الصور النوعية التي تدل بخصائصها وهوياتها على صفات الله وذاته", "ozet": "Bir şeyin ismi onunla tanınan şeydir; Allah'ın isimleri, O'nun sıfat ve zâtına delalet eden türsel suretlerdir.", "iddia": ["I15"], "iliski": "genisletme"}
{"seg": "QASHANI:1:1", "konu": "الله: zâtın ismi", "tur": "isari", "alim": "el-Kâşânî", "alinti": "و { الله } اسم للذات الإلهية من حيث هي هي على الإطلاق", "ozet": "Allah, ilahi zâtın, sıfatlarla nitelenmeden veya nitelenmemeden bağımsız olarak, mutlak ismidir.", "iddia": ["I37"], "iliski": "yeni"}
{"seg": "QASHANI:1:1", "konu": "الرحمن / الرحيم farkı", "tur": "isari", "alim": "el-Kâşânî", "alinti": "و { الرحمن } هو المفيض للوجود والكمال على الكل بحسب ما تقتضي الحكمة وتحتمل القوابل على وجه البداية.", "ozet": "Rahmân, hikmetin gerektirdiği ve kabiliyetlerin taşıdığı ölçüde varlığı ve kemali herkese başlangıçta yayandır.", "iddia": ["I49", "I50"], "iliski": "genisletme"}
{"seg": "QASHANI:1:1", "konu": "الرحيم: insana özgü kemal", "tur": "isari", "alim": "el-Kâşânî", "alinti": "و { الرحيم } هو المفيض للكمال المعنوي المخصوص بالنوع الإنساني بحسب النهاية", "ozet": "Rahîm, insan türüne özgü manevi kemali sonda yayandır; 'dünya Rahmânı, ahiret Rahîmi' denmiştir.", "iddia": ["I50"], "iliski": "genisletme"}
{"seg": "QASHANI:1:1", "konu": "باء بسم الله: varlığın ilk zuhuru", "tur": "isari", "alim": "el-Kâşânî", "alinti": "ظهرت الموجودات من باء بسم الله إذ هي الحرف الذي يلي الألف الموضوعة بإزاء ذات الله", "ozet": "Varlıklar besmelenin bâ'sından zuhur etti; bâ, Allah'ın zâtına karşılık olan elife komşu harftir ve ilk akla işaret eder.", "iddia": ["I1"], "iliski": "yeni"}
{"seg": "QASHANI:1:1", "konu": "besmelenin harf sayısı", "tur": "isari", "alim": "el-Kâşânî", "alinti": "والحروف الملفوظة لهذه الكلمة ثمانية عشر، والمكتوبة تسعة عشر.", "ozet": "Besmelede telaffuz edilen harf on sekiz, yazılan on dokuzdur; on sekiz, on sekiz bin âleme işaret sayılır.", "iddia": [], "iliski": "yeni"}
{"seg": "QASHANI:1:1#2", "konu": "bâ'nın elifi ve uzatılması", "tur": "isari", "alim": "el-Kâşânî", "alinti": "وأمر بتطويل باء بسم الله تعويضا عن ألفها", "ozet": "Elifi düştüğü için besmelenin bâ'sının uzatılması emredilmiş; bu, ulûhiyetin rahmet suretinde gizlenmesine işaret sayılır.", "iddia": ["I1"], "iliski": "yeni"}
{"seg": "QASHANI:1:1#2", "konu": "elifin düşmesi hadisi", "tur": "hadis", "alim": "Hz. Peygamber'e nispet", "alinti": "سرقها الشيطان", "ozet": "Bâ'nın elifi nereye gitti diye sorulunca Peygamber 'Şeytan çaldı' demiş; el-Kâşânî bunu aktarır.", "iddia": [], "iliski": "yeni", "derece": "gösterilmemiş"}
{"seg": "QASHANI:1:1#2", "konu": "tevhid mertebeleri ve besmele", "tur": "isari", "alim": "el-Kâşânî", "alinti": "فتوحيد الأفعال مقدم على توحيد الصفات وهو على توحيد الذات", "ozet": "Fiillerin tevhidi sıfatların tevhidinden, o da zâtın tevhidinden öncedir; zâta ulaşan besmeleyi okuyan olur.", "iddia": [], "iliski": "yeni"}
{"seg": "QUSHAYRI:v1p8", "konu": "الباء في بسم الله", "tur": "isari", "alim": "el-Kuşeyrî", "alinti": "الباء في بسم الله حرف التضمين ؛ أي بالله ظهرت الحادثات", "ozet": "Besmeledeki bâ, 'Allah ile' anlamını taşır: bütün yaratılmışlar O'nunla ortaya çıkmıştır.", "iddia": ["I1"], "iliski": "genisletme"}
{"seg": "QUSHAYRI:v1p8", "konu": "بسم الله ve بالله farkı", "tur": "tefsir_dirayet", "alim": "el-Kuşeyrî", "alinti": "وقال : { بسم الله } ولم يقل بالله على وجه التبرك بذكر اسمه عند قوم", "ozet": "'Bi'llâh' denmeyip 'bismillâh' denmesi bazılarına göre isim anarak teberrük içindir, bazılarına göre yeminden ayırmak içindir.", "iddia": ["I1", "I19"], "iliski": "genisletme"}
{"seg": "QUSHAYRI:v1p8", "konu": "الاسم هو المسمى", "tur": "kelam", "alim": "ulemâ (Kuşeyrî nakleder)", "alinti": "ولأن الاسم هو المسمى عند العلماء", "ozet": "Üçüncü gerekçe: ulemaya göre isim müsemmânın kendisidir.", "iddia": ["I19"], "iliski": "destek"}
{"seg": "QUSHAYRI:v1p8", "konu": "بسم harflerinin işaretleri", "tur": "isari", "alim": "bir topluluk (Kuşeyrî nakleder)", "alinti": "وآخرون يذكرون عند الباء بهاءه ، وعند السين سناءه ، وعند الميم ملكه", "ozet": "Bâ'da Allah'ın bahâsı, sîn'de senâsı, mîm'de mülkü hatırlanır; başkaları bâ'da birr, sîn'de sır, mîm'de minnet der.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p24#2", "konu": "besmele harflerinin işareti (İbn Atâ)", "tur": "isari", "alim": "el-Abbâs b. Atâ", "alinti": "الباء بره لأرواح الأنبياء بإلهام الرسالة والنبوة", "ozet": "Bâ peygamberlerin ruhlarına risalet ve nübüvvet ilhamıyla birr, sîn ma'rifet ehline sır, mîm müridlere minnettir.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p24#2", "konu": "بسم الله: Cüneyd", "tur": "isari", "alim": "el-Cüneyd", "alinti": "بسم الله هيبته ، وفي الرحمن عونه ، وفي الرحيم مودته ومحبته", "ozet": "Cüneyd'e göre besmelede Allah ismi heybet, Rahmân yardım, Rahîm sevgi ve muhabbettir.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p24#2", "konu": "بسم لبقاء هياكل الخلق", "tur": "isari", "alim": "bir söz (kîl)", "alinti": "إن ' بسم ' لبقاء هياكل الخلق", "ozet": "'Bism' yaratılmışların bedenlerinin kalması içindir; kitap doğrudan Allah'ın ismiyle açılsaydı peygamber ve veli dışındakiler erirdi.", "iddia": ["I15"], "iliski": "yeni"}
{"seg": "SULAMI:v1p24#2", "konu": "بسم: Cafer es-Sâdık", "tur": "isari", "alim": "Câfer b. Muhammed (Ali b. Mûsâ er-Rızâ'dan, babasından)", "alinti": "' بسم ' الباء بقاؤه والسين أسماؤه والميم ملكه", "ozet": "Bâ O'nun bekâsı, sîn isimleri, mîm mülküdür; müminin imanı bekâyı, mürid isimleri anmaktır.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p24#2", "konu": "Hz. Peygamber'den bahâ-senâ-mecd", "tur": "hadis", "alim": "Peygamber'e nispet (sahih ise)", "alinti": "الباء بهاؤه والسين سناؤه ، والميم مجده", "ozet": "Peygamberden, sahih ise, bâ O'nun bahâsı, sîn senâsı, mîm mecdidir diye rivayet edilir.", "iddia": [], "iliski": "yeni", "derece": "إن صح هذا (kaynak sıhhatten şüphe eder)"}
{"seg": "SULAMI:v1p26", "konu": "بسم ثلاثة أحرف", "tur": "isari", "alim": "", "alinti": "فالباء باب النبوة ، والسين سر النبوة", "ozet": "Bâ nübüvvet kapısı, sîn nübüvvetin sırrı, mîm dinin mülküdür.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p26", "konu": "الله ismi: Vâsıtî", "tur": "isari", "alim": "Muhammed b. Mûsâ el-Vâsıtî", "alinti": "ما دعى الله أحد باسم من أسمائه ، إلا ولنفسه في ذلك نصيب إلا قوله ' الله '", "ozet": "Allah'ı herhangi bir isimle çağıran kendine pay çıkarır; yalnız 'Allah' ismi hariçtir, bu isim vahdâniyete çağırır.", "iddia": ["I40"], "iliski": "destek"}
{"seg": "SULAMI:v1p26", "konu": "بسم الله ve kün", "tur": "isari", "alim": "el-Hüseyn", "alinti": "بسم الله منك منزلة ' كن ' منه", "ozet": "Hüseyn'e göre senin 'bismillâh' demen, Allah'ın 'kün' demesi gibidir; şeyler bu sözle gerçekleşir.", "iddia": ["I3"], "iliski": "yeni"}
{"seg": "SULAMI:v1p26", "konu": "Şiblî: Allah demek", "tur": "isari", "alim": "eş-Şiblî", "alinti": "ما قال الله أحد سوى الله", "ozet": "Şiblî: Allah'ı kendinden başka kimse 'Allah' diye anmaz, çünkü herkes payla anar.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p26", "konu": "Hazzâz: Allah ismi", "tur": "isari", "alim": "Ebû Said el-Harrâz", "alinti": "ضاع اسمي فلا اسم لي", "ozet": "Harrâz, Allah'tan başkasını unutan kimsenin hâlini anlatır: 'Ne istersin' denince 'Allah' der.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p28", "konu": "Hallâc: zikir ve harfler", "tur": "isari", "alim": "el-Hüseyn b. Mansûr", "alinti": "له من الأسماء معناها والحروف مجراها", "ozet": "Hallâc: Allah'ı hakikatiyle kimse anamaz; isimlerin manası O'nun, harfler yalnız mecrasıdır.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p28", "konu": "الله harfleri", "tur": "isari", "alim": "", "alinti": "وقيل : إن الألف الأول من اسمه الله ابتداؤه ، واللام الأول لام المعرفة", "ozet": "Allah isminin harfleri şöyle yorumlanır: elif başlangıçtır, ilk lâm ma'rifet lâmıdır, ikinci lâm âlâ ve nimet lâmıdır, hâ nihayettir.", "iddia": ["I37"], "iliski": "yeni"}
{"seg": "SULAMI:v1p28", "konu": "Nûrî ve Cüneyd: Allah Allah", "tur": "isari", "alim": "Ebû'l-Hüseyn en-Nûrî, el-Cüneyd", "alinti": "إن كنت القائل الله فالله ولست القائل له", "ozet": "Nûrî yedi gün 'Allah Allah' diyerek vecde kalınca Cüneyd, söyleyen sen isen nefsinle, Allah ise Allah'sın der.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p28", "konu": "الله: el-mâni'", "tur": "isari", "alim": "", "alinti": "الله هو المانع الذي يمنع الوصول إليه", "ozet": "Allah ismi, kendisine ulaşılmasını engelleyen anlamındadır; isme bile hakikaten ulaşılamıyorsa zâta ulaşmak daha zordur.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p30", "konu": "الله harf yorumları", "tur": "isari", "alim": "", "alinti": "وقيل : إن الإشارة في الألف هو قيام الحق بنفسه وانفصاله عن جميع خلقه", "ozet": "Elif Hakk'ın kendiyle kaim ve yaratılmışlardan ayrı olduğuna işarettir, çünkü elif başka harfe bitişmez.", "iddia": ["I37"], "iliski": "yeni"}
{"seg": "SULAMI:v1p30", "konu": "harf düşürme", "tur": "isari", "alim": "", "alinti": "فإذا أسقطت منه الألف يكون ' لله ' فإذا أسقطت إحدى لاميه يكون ' له '", "ozet": "Allah isminden elif düşse 'lillâh', bir lâm düşse 'lehû' kalır; Allah'tan başka hiçbir ismin harf düşünce ismi kalmaz.", "iddia": ["I37"], "iliski": "yeni"}
{"seg": "SULAMI:v1p30", "konu": "tüm isimler bu isimde", "tur": "isari", "alim": "", "alinti": "إن الأسماء كلها داخل في هذا الاسم وخارج منه", "ozet": "Bütün isimler bu isme dahildir ve ondan çıkar; Allah bu ismi yaratılmışlardan ayırmış, diğer isimlerin türemelerinde ise ortak olmuştur.", "iddia": ["I40"], "iliski": "destek"}
{"seg": "SULAMI:v1p30", "konu": "İbn Atâ: Allah", "tur": "isari", "alim": "Ebû'l-Abbâs b. Atâ", "alinti": "قوله : ' الله ' هو إظهار هيبته وكبريائه", "ozet": "İbn Atâ'ya göre 'Allah' demek Allah'ın heybet ve kibriyasının izharıdır.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p31", "confirm": "", "konu": "Harrâz: Allah kelimesi", "tur": "isari", "alim": "Ebû Said el-Harrâz", "alinti": "إن الله عز وجل أول ما دعا عباده دعاهم إلى كلمة واحدة", "ozet": "Allah kullarını ilk önce tek kelimeye çağırdı: 'Allah'; ardından Ahad, Samed ve diğerleri eklenmiştir.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p31", "konu": "Allah ismi: ta'alluk, tehallük", "tur": "isari", "alim": "", "alinti": "إن كل أسمائه تتهيىء أن يتخلق به إلا قوله الله فإنما هو للتعلق دون التخلق", "ozet": "Allah'ın diğer isimleriyle ahlaklanılabilir; 'Allah' ismi yalnız bağlanmak içindir, ahlaklanmak için değil.", "iddia": ["I40"], "iliski": "destek"}
{"seg": "SULAMI:v1p31", "konu": "Câfer: Allah dört harf", "tur": "isari", "alim": "Câfer es-Sâdık (Mansûr'un isnadıyla)", "alinti": "الله هو الاسم المتفرد لا يضاف إلى شيء بل تضاف الأشياء كلها إليه", "ozet": "Allah tek başına kalan isimdir; hiçbir şeye izafe edilmez, her şey O'na izafe edilir; elif tevhidin direğidir.", "iddia": ["I40"], "iliski": "destek"}
{"seg": "SULAMI:v1p32", "konu": "الرحمن: ikram ve rahmet", "tur": "isari", "alim": "", "alinti": "باسم الرحمن خرجت جميع الكرامات للمؤمنين", "ozet": "Rahmân ismiyle müminlere iman, taat, velayet, ismet gibi tüm ikramlar çıkmıştır; yaratılmışlardan hiçbiri bu isme layık değildir.", "iddia": ["I52"], "iliski": "destek"}
{"seg": "SULAMI:v1p32", "konu": "الرحمن isim gerekçesi", "tur": "lugat", "alim": "", "alinti": "ولما عمت رحمته في العاجلة على الولي والعدو في معايشهم وأرزاقهم وغير ذلك سمي رحمن", "ozet": "Rahmetini dünyada dosta ve düşmana, geçim ve rızıkta yaydığı için 'Rahmân' adını almıştır.", "iddia": ["I49", "I54"], "iliski": "destek"}
{"seg": "SULAMI:v1p32", "konu": "İbn Atâ: Rahmân", "tur": "isari", "alim": "İbn Atâ", "alinti": "وقال ابن عطاء : في اسمه الرحمن عونه ونصرته", "ozet": "İbn Atâ: Rahmân isminde Allah'ın yardımı ve nusreti vardır.", "iddia": [], "iliski": "yeni"}
{"seg": "SULAMI:v1p32", "konu": "Vâsıtî: Rahmân ve Rahîm", "tur": "tefsir_dirayet", "alim": "el-Vâsıtî", "alinti": "الرحمن لا يتقرب إليه أحد إلا بصرف رحمانيته ، والرحيم يتقرب إليه بالطاعات لأنه يشارك فيه رسول الله", "ozet": "Rahmân'a ancak O'nun rahmâniyetiyle yaklaşılır; Rahîm'e taatle yaklaşılır, çünkü Rahîm'de Peygamber de ortaktır (9:128).", "iddia": ["I52"], "iliski": "destek"}
{"seg": "SULAMI:v1p33", "konu": "الرحيم: isimlenme", "tur": "tefsir_dirayet", "alim": "", "alinti": "فلذلك لم يمنعوا أن يتسموا بالرحيم ومنعوا بالتسمية بالرحمن", "ozet": "Rahîm, yaratılmışların geçimi ve beden maslahatı için çıkan rahmettir; bu yüzden Rahîm ile isimlenmek yasaklanmamış, Rahmân ile yasaklanmıştır.", "iddia": ["I52"], "iliski": "destek"}
{"seg": "SULAMI:v1p33", "konu": "Rahîm: Muhammed", "tur": "isari", "alim": "", "alinti": "والرحيم هو الذي يقبلك بجميع عيوبك إذا أقبلت عليه", "ozet": "Rahîm ile Muhammed (9:128) gönderilmiştir; Rahîm, yönelene bütün ayıplarıyla kabul eden, yüz çevirene de koruyandır.", "iddia": ["I52"], "iliski": "genisletme"}
{"seg": "SULAMI:v1p33", "konu": "Câfer: Rahmân ve Rahîm", "tur": "isari", "alim": "Câfer es-Sâdık (Mansûr'un isnadıyla)", "alinti": "فاسم الرحمن للمرادين لاستغراقهم في الأنوار والحقائق ، والرحيم للمريدين", "ozet": "Rahmân istenenler için (nur ve hakikatte boğulmuş), Rahîm isteyenler için (kendileriyle kalıp zâhiri düzeltenler) isimdir.", "iddia": ["I50"], "iliski": "genisletme"}
{"seg": "SULAMI:v1p33#2", "bos": true, "neden": "yalnız 2. ayet başlığı"}
{"seg": "TUSTARI:1:1", "konu": "بسم harfleri (Tüsterî)", "tur": "isari", "alim": "Sehl et-Tüsterî (Ebû Bekr'den)", "alinti": "الباء بهاء الله عز وجل: والسين سناء الله عز وجل. والميم مجد الله عز وجل.", "ozet": "Sehl'e göre bâ Allah'ın bahâsı, sîn senâsı, mîm mecdidir.", "iddia": [], "iliski": "yeni"}
{"seg": "TUSTARI:1:1", "konu": "الله: el-ism el-a'zam", "tur": "isari", "alim": "Sehl et-Tüsterî", "alinti": "والله: هو الاسم الأعظم الذي حوى الأسماء كلها", "ozet": "Allah, bütün isimleri kapsayan en büyük isimdir; elif ile lâm arasında gizli bir harf vardır.", "iddia": ["I40", "I41"], "iliski": "destek"}
{"seg": "TUSTARI:1:1", "konu": "الرحيم ve الرحمن", "tur": "isari", "alim": "Sehl et-Tüsterî", "alinti": "والرحيم: هو العاطف على عباده بالرزق في الفرع والابتداء في الأصل رحمة لسابق علمه القديم.", "ozet": "Rahîm, kullarına rızıkla yönelen ve başlangıçta rahmet olarak yaratandır; Rahmân'da elif-lâm arasındaki harften bir özellik vardır.", "iddia": ["I50"], "iliski": "genisletme"}
{"seg": "TUSTARI:1:1", "konu": "Ali: iki ince isim", "tur": "tefsir_rivayet", "alim": "Ali b. Ebî Tâlib", "alinti": "\" الرحمن الرحيم \" اسمان رقيقان أحدهما أرق من الآخر", "ozet": "Ali'den: Rahmân ve Rahîm iki ince isimdir, biri ötekinden daha incedir; Allah onlarla müminlerin ümitsizliğini giderir.", "iddia": ["I49", "I50"], "iliski": "genisletme"}
{"seg": "AKHFASH:v1p3#2", "konu": "اسم صلة زائدة", "tur": "nahiv", "alim": "el-Ahfeş", "alinti": "\"اسم\" [في التسمية] صلة زائدة، زيدت ليخرج بذكرها من حكم القسم الى قصد التبرك", "ozet": "'İsm' fazladır; yemin hükmünden teberrük kastına çıkmak için eklenmiştir, asıl söz 'bi'llâh'tır.", "iddia": ["I1", "I19"], "iliski": "karsi"}
{"seg": "AKHFASH:v1p3#2", "konu": "elifin yazıdan düşmesi", "tur": "nahiv", "alim": "el-Ahfeş", "alinti": "وحذفت الألف من \"بسم\" من الخط تخفيفا لكثرة الاستعمال", "ozet": "Bismin elifi kullanım çokluğundan yazıda düşmüş; 'bismi'r-Rahmân' yazılsa düşmez.", "iddia": [], "iliski": "yeni"}
{"seg": "AKHFASH:v1p3#2", "konu": "vasl elifi", "tur": "nahiv", "alim": "el-Ahfeş", "alinti": "والألف في \"اسم\" ألف وصل، لانك تقول: \"سمي\"", "ozet": "İsmdeki elif vasl elifidir; tasgirde 'sumey' dendiği için düşer, sakin harfle başlamayı mümkün kılmak için konmuştur.", "iddia": ["I13"], "iliski": "yeni"}
{"seg": "AKHFASH:v1p7", "konu": "الرحمن الرحيم: elif-lâm vasl", "tur": "nahiv", "alim": "el-Ahfeş", "alinti": "وأما قوله: {الرحمن الرحيم الحمد} فوصلت هذه الأسماء التي في أوائلها الالف واللام", "ozet": "Elif-lâm ile başlayan isimlerde elif bir önceki sözle bitişince düşer; elif-lâm tek zâid harf gibidir.", "iddia": [], "iliski": "yeni"}
{"seg": "FARRA:v1p1#2", "konu": "elifin hazfi", "tur": "nahiv", "alim": "el-Ferrâ", "alinti": "اجتماع القراء وكتاب المصاحف على حذف الألف من «بسم الله الرحمن الرحيم»", "ozet": "Kurrâ ve mushaf kâtipleri besmeledeki elifin düşürülmesinde ittifak etmiştir; 'bismi rabbike'de elif yazılır.", "iddia": [], "iliski": "yeni"}
{"seg": "FARRA:v1p1#2", "konu": "besmele her işin başında", "tur": "kelam", "alim": "el-Ferrâ", "alinti": "ألا ترى أنك تقول: «بسم الله» عند ابتداء كل فعل تأخذ فيه: من مأكل أو مشرب أو ذبيحة.", "ozet": "Yeme, içme, kesme gibi her işe başlarken besmele söylendiği için anlamı bilinen yerde elif düşürülmesi hafif gelmiştir.", "iddia": ["I3", "I9"], "iliski": "destek"}
{"seg": "IBNQUTAYBA-GHARIB:v1p38", "konu": "بسم الله ihtisar", "tur": "nahiv", "alim": "İbn Kuteybe", "alinti": "{بسم الله} اختصار كأنه قال: أبدأ باسم الله. أو بدأت باسم الله.", "ozet": "Besmele kısaltmadır; 'Allah'ın adıyla başlarım' ya da 'başladım' demek gibidir.", "iddia": ["I2"], "iliski": "destek"}
{"seg": "MAJAZ:v1p20#2", "konu": "بسم الله mecazı: gizli fiil", "tur": "nahiv", "alim": "Ebû Ubeyde", "alinti": "فمجاز تفسير قوله «بسم الله» مضمر", "ozet": "Besmelenin mecazı gizlidir: 'her şeyden önce Allah'ın adıyla' gibi; İbn Revâha'nın 'bismi'l-ilâhi ve bihî bedeynâ' beyti şahit gösterilir.", "iddia": ["I2"], "iliski": "destek"}
{"seg": "MAJAZ:v1p21", "konu": "الرحمن / الرحيم mecazı", "tur": "lugat", "alim": "Ebû Ubeyde", "alinti": "«الرحمن» مجازه ذو الرحمة، و «الرحيم» مجازه الراحم", "ozet": "Rahmân 'rahmet sahibi', Rahîm 'merhamet eden' demektir; Araplar aynı manada iki lafzı tek kökten türetir, nedmân/nedîm gibi.", "iddia": ["I49", "I50"], "iliski": "karsi"}
{"seg": "SAMIN-DURR:1:1", "konu": "besmele fiili (basmele)", "tur": "nahiv", "alim": "es-Semîn el-Halebî", "alinti": "مصدر بسمل، أي قال: بسم الله، نحو: حوقل وهيلل وحمدل", "ozet": "Besmele, 'bismillâh' demek anlamındaki basmele fiilinin masdarıdır; haukale, heylele gibi nahit yoluyla türemiştir, bazıları bunu mülevved sayar.", "iddia": ["I16"], "iliski": "yeni"}
{"seg": "SAMIN-DURR:1:1", "konu": "باء الاستعانة", "tur": "nahiv", "alim": "es-Semîn el-Halebî", "alinti": "والباء هنا للاستعانة كعملت وبالقدوم", "ozet": "Buradaki bâ istiâne içindir: 'Allah'tan yardım isteyerek okurum'; bâ'nın başka anlamları da sayılır.", "iddia": ["I1"], "iliski": "karsi"}
{"seg": "SAMIN-DURR:1:1", "konu": "bâ'nın anlamları", "tur": "nahiv", "alim": "es-Semîn el-Halebî", "alinti": "الإلصاق حقيقة أو مجازا، نحو: مسحت برأسي، مررت بزيد، والسببية", "ozet": "Bâ ilsak, sebep, musâhabe, bedel, kasem, zarf, ta'diye, tab'îz, mukabele ve mücâveze anlamlarında gelir; cumhur ilsak veya ta'diyeye indirger.", "iddia": ["I1"], "iliski": "genisletme"}
{"seg": "SAMIN-DURR:1:1#2", "konu": "اسم tanımı", "tur": "nahiv", "alim": "es-Semîn el-Halebî", "alinti": "والاسم لغة: ما أبان عن مسمى", "ozet": "İsim sözlükte müsemmâyı açıklayandır; terim olarak tek başına mana bildiren ve zaman kapsamayan lafızdır; tesmiye lafzı manaya delil kılmaktır.", "iddia": ["I15", "I16"], "iliski": "genisletme"}
{"seg": "SAMIN-DURR:1:1#2", "konu": "bâ'nın zâid kullanımı", "tur": "nahiv", "alim": "es-Semîn el-Halebî", "alinti": "وقد تزاد مطردة وغير مطردة، فالمطردة في فاعل \" كفى \"", "ozet": "Bâ düzenli olarak 'kefâ' fâilinde, 'leyse'nin haberinde ve 'bihasbike'de zâid gelir; bu kural dışı kullanımlar da örneklenir.", "iddia": [], "iliski": "yeni"}
{"seg": "SAMIN-DURR:1:1#3", "konu": "الاسم عين المسمى mi", "tur": "kelam", "alim": "es-Semîn; Ebü'l-Bekâ", "alinti": "واختلف الناس: هل الاسم عين المسمى أو غيره؟", "ozet": "İsmin müsemmânın kendisi mi başkası mı olduğu uzun bir tartışmadır; ismin ona izafesi sorun çıkarır, Ebü'l-Bekâ üç cevap verir.", "iddia": ["I19"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#3", "konu": "اسم zâid", "tur": "nahiv", "alim": "Ebû Ubeyde, el-Ahfeş, Kutrub", "alinti": "وإليه ذهب أبو عبيدة والأخفش وقطرب.", "ozet": "'İsm'in zâid olduğunu Ebû Ubeyde, Ahfeş ve Kutrub savunur; Ahfeş'e göre yeminden teberrüke çıkmak içindir, Kutrub'a göre ta'zîm içindir; yazar ikisini zayıf bulur.", "iddia": ["I1"], "iliski": "karsi"}
{"seg": "SAMIN-DURR:1:1#3", "konu": "اسم iştikakı: Basra ve Kûfe", "tur": "lugat", "alim": "Basralılar; Kûfeliler", "alinti": "فذهب أهل البصرة إلى أنه مشتق من السمو وهو الارتفاع", "ozet": "Basralılar ismi yükselmek (sümüvv) kökünden, Kûfeliler vesm (işaret) kökünden türetir; Kûfelilerinki mana bakımından doğru, sarf bakımından bozuktur.", "iddia": ["I13", "I27", "I30"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#4", "konu": "Basralıların delili", "tur": "lugat", "alim": "Basralılar", "alinti": "استدل البصريون على مذهبهم بتكسيرهم له على \" أسماء \" وتصغيرهم له على سمي", "ozet": "Basralılar çoğul 'esmâ' ve tasgîr 'sumey'e dayanır; vesm olsaydı 'evsâm' ve 'vesîm' denirdi.", "iddia": ["I27", "I30"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#4", "konu": "iştikak tartışmasının sonucu", "tur": "kelam", "alim": "Ehl-i sünnet; Mu'tezile", "alinti": "ومن قال بأنه مشتق من الوسم يقول: كان الله في الأزل بلا اسم ولا صفة", "ozet": "Yükselmekten türetenler Allah'ın isim ve sıfatlarının ezeli olduğunu söyler (Ehl-i sünnet); vesm diyenler ezelde isimsiz olduğunu (Mu'tezile), ki bu daha büyük hata sayılır.", "iddia": ["I19", "I30"], "iliski": "genisletme"}
{"seg": "SAMIN-DURR:1:1#4", "konu": "isimin beş lugatı", "tur": "lugat", "alim": "Ahmed b. Yahyâ (Sa'leb)", "alinti": "وفي الاسم خمس لغات: \" اسم \" بضم الهمزة وكسرها", "ozet": "İsmin beş lugatı vardır: ism, usm, sim, sum, sumâ; Sa'leb'e göre sum sümüvvden, sim semeyten türer.", "iddia": ["I13"], "iliski": "yeni"}
{"seg": "SAMIN-DURR:1:1#5", "konu": "بسم elifinin hazfi", "tur": "nahiv", "alim": "en-Nehhâs; Kisâî, Ahfeş", "alinti": "وإنما حذفوها حين يضاف الاسم إلى الجلالة خاصة لكثرة الاستعمال", "ozet": "Elif yalnız Celâle'ye izafede düşürülmüştür; 'bismi'r-Rahmân'da kalır; Kisâî ve Ahfeş öteki isimlerde de düşebilir der.", "iddia": [], "iliski": "yeni"}
{"seg": "SAMIN-DURR:1:1#5", "konu": "mahzuf müteallak", "tur": "nahiv", "alim": "Basralılar; Kûfeliler; ez-Zemahşerî", "alinti": "فذهب أهل البصرة إلى أن المتعلق به اسم، وذهب أهل الكوفة إلى أنه فعل", "ozet": "Müteallak Basralılara göre isim (ibtidâî bismillâh), Kûfelilere göre fiildir; Zemahşerî fiili sona alır ve takdîm ihtisas ifade eder.", "iddia": ["I2"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#5", "konu": "Zemahşerî: ihtisas", "tur": "belagat", "alim": "ez-Zemahşerî", "alinti": "ليفيد التقديم الاختصاص لأنه وقع ردا على الكفرة الذين كانوا يبدؤون بأسماء آلهتهم", "ozet": "Fiilin sona alınması ihtisas içindir; müşrikler 'bismi'l-Lât, bismi'l-Uzzâ' diyerek başladıkları için bu bir reddiyedir.", "iddia": ["I2", "I3"], "iliski": "genisletme"}
{"seg": "SAMIN-DURR:1:1#6", "konu": "اقرأ باسم ربك itirazı", "tur": "ayet_ayet", "alim": "ez-Zemahşerî", "alinti": "ثم أجاب بأن تقديم الفعل في سورة العلق أوقع لأنها أول سورة نزلت فكان الأمر بالقراءة أهم", "ozet": "Alak 96:1'de fiilin öne alınması, ilk inen sure olduğu ve okuma emrinin daha önemli olduğu için daha uygundur.", "iddia": ["I6"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#6", "konu": "fiil emir mi haber mi", "tur": "nahiv", "alim": "el-Ferrâ; ez-Zeccâc", "alinti": "فذهب الفراء أنه أمر تقديره: اقرأ أنت باسم الله، وذهب الزجاج أنه خبر", "ozet": "Ferrâ'ya göre mahzuf fiil emirdir ('Allah'ın adıyla oku'), Zeccâc'a göre haberdir ('okurum' ya da 'başlarım').", "iddia": ["I2"], "iliski": "genisletme"}
{"seg": "SAMIN-DURR:1:1#6", "konu": "الله: alem", "tur": "lugat", "alim": "es-Semîn; ez-Zemahşerî", "alinti": "وهو علم على المعبود بحق، لا يطلق على غيره", "ozet": "Allah hak mabudun özel adıdır, başkasına denmez; Zemahşerî'ye göre gâlebiyetle alem olmuş; mürtecel olması doğrudur, Sîbeveyh rüyada bunu söyler.", "iddia": ["I37", "I40"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#6", "konu": "Allah ismi türevi: lâhe", "tur": "lugat", "alim": "iştikak diyenler", "alinti": "ومنهم من قال: هو مشتق من لاه يليه أي ارتفع، ومنه قيل للشمس: إلاهة", "ozet": "Bazıları Allah'ı 'lâhe yelîhi' (yükseldi) kökünden türetir; güneşe 'ilâhe' denmesi yükselmesindendir veya tapınıldığındandır.", "iddia": ["I37", "I44"], "iliski": "genisletme"}
{"seg": "SAMIN-DURR:1:1#7", "konu": "lâhe yelûhu: gizlendi", "tur": "lugat", "alim": "", "alinti": "ومنهم من قال: \" هو مشتق من لاه يلوه لياها. أي احتجب", "ozet": "Bazıları 'lâhe yelûhu' (gizlendi) kökünden türetir; elif aslîdir, lâm-ı ta'rif idğam edilir.", "iddia": ["I37"], "iliski": "genisletme"}
{"seg": "SAMIN-DURR:1:1#7", "konu": "ilâh: ibâdet, sükûn, hayret, feza", "tur": "lugat", "alim": "", "alinti": "ومنهم من جعله مشتقا من أله، وأله لفظ مشترك بين معان وهي: العبادة والسكون والتحير والفزع", "ozet": "Elehe kökü ibadet, sükûn, hayret ve fezeâ anlamlarını taşır; ilâh kulların ona ibadet ettiği, sığındığı, şaşırdığı kimsedir; Rü'be ve 7:127 şahit.", "iddia": ["I37"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#7", "konu": "Hz. Ali: sıfatlarda hayret", "tur": "tefsir_rivayet", "alim": "Emîrülmü'minîn Ali", "alinti": "كل دون صفاته تحبير الصفات وضل هناك تصاريف اللغات", "ozet": "Ali'den: Allah'ın sıfatları karşısında sıfat tahbiri aciz kalır, lügatın tasarrufları kaybolur.", "iddia": ["I37"], "iliski": "genisletme"}
{"seg": "SAMIN-DURR:1:1#8", "konu": "الله: vele kökü", "tur": "lugat", "alim": "el-Halîl'e nispet", "alinti": "ومنهم من قال: هو مشتق من وله لكون كل مخلوق والها نحوه", "ozet": "Halîl'e nispet edilen görüşe göre Allah, her yaratığın kendisine vâlih olduğu için 'velehe' kökündendir; vezni fi'âl, mef'ûl anlamındadır.", "iddia": ["I46"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#8", "konu": "Halîl'e iki itiraz", "tur": "lugat", "alim": "", "alinti": "ولم يجمع \" إله \" إلا على آلهة", "ozet": "Halîl'in görüşüne itiraz: hemze vâvdan bedel olsaydı asıl söylenirdi ve çoğul 'evlihe' olurdu; oysa çoğul yalnız 'âlihe'dir.", "iddia": ["I46"], "iliski": "karsi"}
{"seg": "SAMIN-DURR:1:1#8", "konu": "Celâle'nin elifinin yazılışı", "tur": "nahiv", "alim": "", "alinti": "قالوا: وحذفت الألف التي قبل الهاء خطا لئلا يشبه بخط \" اللات \" اسم الصنم", "ozet": "Hâ'dan önceki elif, 'el-Lât' putunun yazısına benzemesin diye yazıdan düşmüştür; başka gerekçeler de verilir.", "iddia": [], "iliski": "yeni"}
{"seg": "SAMIN-DURR:1:1#9", "konu": "Allah ismi Süryânîdir", "tur": "lugat", "alim": "Ebû Zeyd el-Belhî", "alinti": "ومن غريب ما نقل فيه أيضا أنه ليس بعربي بل هو معرب، وهو سرياني الوضع", "ozet": "Garip bir görüş: Allah ismi Süryânîdir, asıl 'lâhâ'; Arapça'ya alınmıştır (Belhî).", "iddia": ["I37"], "iliski": "yeni"}
{"seg": "SAMIN-DURR:1:1#9", "konu": "Allah sıfat mı isim mi", "tur": "kelam", "alim": "ez-Zemahşerî (reddeder)", "alinti": "ومن غريب ما نقل فيه أيضا أنه صفة وليس باسم", "ozet": "Allah'ın sıfat olduğu görüşü reddedilir: onunla nitelenir ama onunla nitelenmez; sıfatları cereyan edeceği bir mevsûf ister, bu yüzden isimdir.", "iddia": ["I37"], "iliski": "yeni"}
{"seg": "SAMIN-DURR:1:1#9", "konu": "es-Süheylî ve İbnü'l-Arabî: el aslî", "tur": "nahiv", "alim": "es-Süheylî; İbnü'l-Arabî", "alinti": "ونقل السهيلي وابن العربي فيه قولا غريبا وهو أن الألف واللام فيه أصلية غير زائدة", "ozet": "İkisine göre Allah'taki elif-lâm asıldır; reddedilir, çünkü vezni fi'âl olurdu ve tenvîn alması gerekirdi.", "iddia": ["I37"], "iliski": "yeni"}
{"seg": "SAMIN-DURR:1:1#10", "konu": "الرحمن الرحيم: iştikak", "tur": "nahiv", "alim": "es-Semîn; İbnü'l-Arabî", "alinti": "الرحمن الرحيم: صفتان مشتقتان من الرحمة، وقيل: الرحمن ليس مشتقا", "ozet": "İkisi rahmetten türeyen sıfatlardır; Rahmân'ın türemediği de söylenir, çünkü Araplar onu bilmiyordu (25:60); İbnü'l-Arabî sıfatı bilmediklerini söyler.", "iddia": ["I53"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#10", "konu": "Rahmân bedel mi", "tur": "nahiv", "alim": "el-A'lem eş-Şentemerî; es-Süheylî", "alinti": "وذهب الأعلم الشنتمري إلى أن \" الرحمن \" بدل من اسم الله لا نعت له", "ozet": "A'lem'e göre Rahmân Allah'tan bedeldir, çünkü alem-i gâlibedir ve tâbi olmadan gelir (55:1-2, 20:5); Süheylî reddeder, çünkü Allah açıklamaya muhtaç değildir.", "iddia": ["I52"], "iliski": "genisletme"}
{"seg": "SAMIN-DURR:1:1#10", "konu": "الرحمة lugatı", "tur": "lugat", "alim": "ez-Zemahşerî", "alinti": "والرحمة لغة: الرقة والانعطاف، ومنه اشتقاق الرحم", "ozet": "Rahmet sözlükte incelik ve eğilmedir; rahim bundan türer, çünkü cenine eğilir; Allah'a nispeti nimetten mecazdır.", "iddia": ["I58", "I60", "I62"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#11", "konu": "İbn Abbâs: iki ince isim", "tur": "tefsir_rivayet", "alim": "İbn Abbâs; el-Hattâbî; el-Hüseyn b. el-Fadl", "alinti": "وقال الحسين بن الفضل: \" هذا وهم من الراوي، وإنما هما اسمان رفيقان أحدهما أرفق من الآخر", "ozet": "İbn Abbâs'tan 'rakîk' rivayeti Hattâbî'ye göre sorunludur; Hüseyn b. Fadl, 'rafîk' olduğunu söyler; hadis: Allah rafîktir, rıfkı sever.", "iddia": ["I49", "I50"], "iliski": "genisletme"}
{"seg": "SAMIN-DURR:1:1#11", "konu": "Rahmân Rahîm aynı mı", "tur": "tefsir_dirayet", "alim": "", "alinti": "فذهب بعضهم إلى أنهما بمعنى واحد كندمان ونديم", "ozet": "Bazılarına göre aynı anlamdadır (nedmân/nedîm), ya te'kid için ya da Müseylime'ye cevap için; yazar ikincisini çok zayıf bulur.", "iddia": ["I52"], "iliski": "karsi"}
{"seg": "SAMIN-DURR:1:1#11", "konu": "dünya Rahmânı, ahiret Rahîmi", "tur": "tefsir_rivayet", "alim": "Peygamber'e nispet", "alinti": "إذ يقال: \" رحمن الدنيا ورحيم الآخرة \" ، يروى ذلك عن النبي صلى الله عليه وسلم", "ozet": "Her birinin farklı alanı: rahmeti dünyada mümin ve kâfire, ahirette yalnız müminlere; rivayet sırası tersine de gelir.", "iddia": ["I50"], "iliski": "genisletme", "derece": "ruvâ edilir, derece belirtilmemiş"}
{"seg": "SAMIN-DURR:1:1#11", "konu": "Rahmân daha beliğ (Zemahşerî)", "tur": "belagat", "alim": "ez-Zemahşerî", "alinti": "ومنهم من قال: الرحمن أبلغ، ولذلك لا يطلق على غير الباري تعالى، واختاره الزمخشري، وجعله من باب غضبان وسكران", "ozet": "Rahmân daha beliğdir, gadbân/sekrân kalıbıdır, bu yüzden başkasına söylenmez; Rahîm onu tamamlayıcı olarak ince nimetleri kapsar.", "iddia": ["I49", "I50", "I52"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#12", "konu": "Rahîm daha beliğ", "tur": "tefsir_dirayet", "alim": "", "alinti": "ومنهم من عكس فجعل الرحيم أبلغ", "ozet": "Bazıları tersini söyler ('dünya Rahîmi, ahiret Rahmânı' rivayetiyle); yazar Rahmân'ın daha beliğ olduğunu savunur, kıyamette rahmet kat kat fazladır.", "iddia": ["I50"], "iliski": "karsi"}
{"seg": "SAMIN-DURR:1:1#12", "konu": "mübalağa yönleri", "tur": "belagat", "alim": "es-Semîn; Ebû Ubeyde", "alinti": "فمبالغة \" فعلان \" من حيث الامتلاء والغلبة ومبالغة \" فعيل \" من حيث التكرار والوقوع بمحال الرحمة", "ozet": "Fa'lân kalıbı dolup taşma ve galebe yönünden, fa'îl tekrar ve rahmet mahallerine isabet yönünden mübalağadır; fa'lân geçişsiz, fa'îl geçişlidir.", "iddia": ["I49", "I50"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#12", "konu": "Rahmân başkası için kullanılmaz", "tur": "kelam", "alim": "ekser ulema", "alinti": "ولا يطلق على غير الباري تعالى عند أكثر العلماء، لقوله تعالى:", "ozet": "Rahmân çoğu âlime göre Allah'tan başkasına söylenmez (17:110); Rahîm Peygamber için de kullanılır (9:128); Müseylime beyti dikkate alınmaz.", "iddia": ["I25", "I52"], "iliski": "destek"}
{"seg": "SAMIN-DURR:1:1#12", "konu": "Rahmân Arapça değil", "tur": "lugat", "alim": "Sa'leb, el-Müberred", "alinti": "ومن غريب ما نقل فيه أنه معرب، ليس بعربي الأصل، وأنه بالخاء المعجمة", "ozet": "Sa'leb ve Müberred'e göre Rahmân Arapça asıllı değildir, 'rahmân' hâ ile (hâ-i mu'cem) alınmıştır; rahmân beyti örnek.", "iddia": ["I53"], "iliski": "yeni"}
{"seg": "SAMIN-DURR:1:1#13", "konu": "الرحيم Hamd'e vasl", "tur": "kiraat", "alim": "Ümmü Seleme; Kisâî; İbn Atıyye", "alinti": "وفي وصل الرحيم بالحمد ثلاثة أوجه، الذي عليه الجمهور: الرحيم بكسر الميم موصولة بالحمد.", "ozet": "Rahîm'in Hamd'e vaslının üç yüzü: cumhur mîm'i kesre ile vasleder; sükûn ve hemze-i kat' (Ümmü Seleme rivayeti); Kisâî'nin hikâye ettiği mîm fethiyle vasl.", "iddia": [], "iliski": "yeni"}
{"seg": "CORPUSCORANICUM:1:1:kommentar", "konu": "Basmala ve Trinitätsformel", "tur": "tarih", "alim": "Corpus Coranicum (Neuwirth)", "alinti": "Ihr Gebrauch entspricht dem der Trinitätsformel »Im Namen des Vaters und des Sohnes und des Heiligen Geistes« in christlichen Texten", "ozet": "Besmele orta Mekke'den itibaren tüm surelerin başına konur; kullanımı Hıristiyan teslis formülüne denktir ve tek Tanrı hakkında bir ifadeye çevrilmiştir.", "iddia": ["I3"], "iliski": "yeni"}
{"seg": "CORPUSCORANICUM:1:1:kommentar", "konu": "Neml 27:30'da besmele", "tur": "ayet_ayet", "alim": "Corpus Coranicum", "alinti": "Innerhalb eines Surentexts begegnet die Basmala einzig in der spätmittelmekkanischen Sure Q 27:30", "ozet": "Besmele sure metni içinde yalnız Neml 27:30'da, Süleyman'ın Sebe Melikesi'ne yazdığı mektupta geçer.", "iddia": ["I5"], "iliski": "destek"}
{"seg": "CORPUSCORANICUM:1:1:kommentar", "konu": "Rahmân adı ve Rahmân-sureleri", "tur": "tarih", "alim": "Corpus Coranicum; L. Ammann", "alinti": "Auf die mittelmekkanische Herkunft der Basmala verweist vor allem der Gottesname ar-Raḥmān", "ozet": "Rahmân adı orta Mekke'de Rahmân-surelerinde (19, 20, 21, 25, 36, 43, 67) rabb'in yerine geçmiştir; Ammann'a göre Hellsgewißheit'i vurgular; İbranice ha-rahaman ile güney Arabistan'dan gelmiş olabilir.", "iddia": ["I53", "I52"], "iliski": "genisletme"}
{"seg": "CORPUSCORANICUM:1:1:kommentar", "konu": "Rahîm adı 'çevirir'", "tur": "tarih", "alim": "Corpus Coranicum", "alinti": "Die etymologisch und semantisch eng verwandte Prädikation raḥīm ›übersetzt‹ den vorgefundenen Namen noch einmal in das gebräuchliche Arabisch.", "ozet": "Rahîm sıfatı, bulunan Rahmân adını bir kez daha yaygın Arapçaya 'çevirir'.", "iddia": ["I50"], "iliski": "yeni"}
{"seg": "CORPUSCORANICUM:1:1:kommentar", "konu": "besmelenin ayet sayılması ve 15:87", "tur": "tarih", "alim": "Corpus Coranicum (Rubin'e dayanarak)", "alinti": "Das Mitrechnen der Basmala unter die Verse der Sure geht auf Q 15:87 zurück", "ozet": "Besmelenin ayetler arasında sayılması 15:87'deki 'yedi mesânî'ye dayanır; yedi kesin bir sayı değil, ondan küçük yuvarlak sayıdır.", "iddia": [], "iliski": "yeni"}
{"seg": "ABUHAYYAN:1:1", "konu": "Fâtiha mekkî mi medenî mi", "tur": "nuzul", "alim": "Ali, İbn Abbâs, Katâde, Ebü'l-Âliye ve diğerleri; Ebû Hüreyre, Mücâhid ve diğerleri", "alinti": "وقال أبو هريرة ،   وعطاء بن يسار ،   ومجاهد ،   وسواد بن زياد ،   والزهري ،   وعبد الله بن عبيد بن عمير : هي مدنية", "ozet": "Birinci grup Fâtiha'nın mekkî, ikinci grup medenî olduğunu söyler; üçüncü görüşe göre ikisi de; mekkî oluşu 15:87'ye dayanır.", "iddia": [], "iliski": "yeni"}
{"seg": "ABUHAYYAN:1:1", "konu": "باء الجر معانی", "tur": "nahiv", "alim": "Ebû Hayyân", "alinti": "باء الجر تأتي لمعان : للإلصاق ،   والاستعانة ،   والقسم ،   والسبب ،   والحال ،   والظرفية ،   والنقل .", "ozet": "Cer bâ'sı ilsak, istiâne, kasem, sebep, hâl, zarf ve nakil anlamlarında gelir; zâid, bedel, mukabele, mücâveze, isti'lâ da sayılır.", "iddia": ["I1"], "iliski": "genisletme"}
{"seg": "ABUHAYYAN:1:1", "konu": "اسم türemesi", "tur": "lugat", "alim": "Basralılar; Kûfeliler", "alinti": "والبصري يقول : مادته سين وميم وواو ،   والكوفي يقول : واو وسين وميم ،   والأرجح الأول .", "ozet": "Basralılar sîn-mîm-vâv, Kûfeliler vâv-sîn-mîm der; birincisi üstündür.", "iddia": ["I13", "I30"], "iliski": "destek"}
{"seg": "ABUHAYYAN:1:1", "konu": "Allah ismi köken görüşleri", "tur": "lugat", "alim": "İbn İshâk; Ebû Amr; en-Nadr; el-Müberred; el-Halîl", "alinti": "وقيل : إن الألف زائدة ومادته همزة ولام ،   من أله أي فزع ،   قاله ابن إسحاق ،   أو أله تحير ،   قاله أبو عمر ،   وأله عبد ،   قاله النضر ،   أو أله سكن ،   قاله المبرد .", "ozet": "Allah ismi ilâhtan: İbn İshâk 'feza', Ebû Amr 'hayret', Nadr 'ibadet', Müberred 'sükûn'; Halîl 'vele' (taşkın sevinç); lâhe yelîhi (yükseldi) ve lâhe yelûhu (gizlendi) de var.", "iddia": ["I37", "I46"], "iliski": "destek"}
{"seg": "ABUHAYYAN:1:1", "konu": "Allah: Süryânî ve sıfat görüşü", "tur": "lugat", "alim": "Ebû Yezîd el-Belhî", "alinti": "قال أبو يزيد البلخي : هو أعجمي ،   فإن اليهود والنصارى يقولون لاها", "ozet": "Belhî'ye göre Allah ismi yabancıdır, Yahudiler ve Hıristiyanlar 'lâhâ' der; Araplar değiştirerek 'Allah' demiştir; sıfat olduğu görüşü de nakledilir.", "iddia": ["I37"], "iliski": "yeni"}
{"seg": "ABUHAYYAN:1:1", "konu": "Rahmân ve Rahîm vezinleri", "tur": "nahiv", "alim": "Ebû Hayyân; Sa'leb", "alinti": "{ الرحيم } : فعيل محوّل من فاعل للمبالغة", "ozet": "Rahmân fa'lân, rahmetten türer; Rahîm fa'îl, fâilden mübalağa için çevrilmiştir; Sa'leb Rahmân'ın hâ ile yabancı olduğunu söyler.", "iddia": ["I49", "I50"], "iliski": "destek"}
{"seg": "ABUHAYYAN:1:1", "konu": "bismillâh fiili ve Zemahşerî", "tur": "nahiv", "alim": "Kûfeliler; ez-Zemahşerî; Sîbeveyh; Basralılar", "alinti": "وقدره الزمخشري فعلاً غير بدأت وجعله متأخراً ،   قال : تقديره بسم الله أقرأ أو أتلو", "ozet": "Kûfelilere göre bâ'nın müteallakı 'bedeü'; Zemahşerî 'ekreü' ve geç takdîr, ihtisas der; Ebû Hayyân Sîbeveyh'e dayanarak buna katılmaz; Basralılara göre mübtedâ.", "iddia": ["I1", "I2"], "iliski": "destek"}
{"seg": "ABUHAYYAN:1:1", "konu": "isim, müsemmâ, tesmiye", "tur": "kelam", "alim": "Ebû Hayyân; el-Gazâlî, İbnü's-Seyyid, es-Süheylî", "alinti": "والاسم هو اللفظ الدال بالوضع على موجود في العيان", "ozet": "İsim lafız, müsemmâ delâlet olunan, tesmiye lafzı manaya delil kılmaktır; isim ve müsemmâ ayrı; 'tebâreke ismü rabbike' mecazen müsemmâ.", "iddia": ["I19"], "iliski": "genisletme"}
{"seg": "ABUHAYYAN:1:1", "konu": "es-Süheylî: 'sebbih isme rabbike'", "tur": "belagat", "alim": "es-Süheylî", "alinti": "بأنه أقحم الاسم تنبيهاً على أن المعنى سبح ربك", "ozet": "Süheylî'ye göre 87:1'de 'ism' tembih için eklenmiştir: 'Rabbini tesbih et'; kalp zikri müsemmâya, dil zikri lafza bağlıdır; 53:23 'sadece isimler' sahte isimlerdir.", "iddia": ["I18", "I28"], "iliski": "destek"}
{"seg": "ABUHAYYAN:1:1", "konu": "elifin hazfi: Kisâî, Ahfeş, Ferrâ", "tur": "nahiv", "alim": "el-Kisâî, el-Ahfeş, el-Ferrâ", "alinti": "وقال الفراء : لا تحذف إلا مع { بسم الله الرحمن الرحيم } ،   لأن الاستعمال إنما كثر فيه", "ozet": "Kisâî ve Ahfeş öteki isimlerde de elifin düşeceğini, Ferrâ yalnız besmelede düşeceğini söyler.", "iddia": [], "iliski": "yeni"}
{"seg": "ABUHAYYAN:1:1", "konu": "Rahmân sıfat mı bedel mi", "tur": "nahiv", "alim": "el-A'lem; es-Süheylî; cemaat", "alinti": "قال أبو زيد السهيلي : البدل فيه عندي ممتنع", "ozet": "Cemaate göre Rahmân sıfattır; A'lem alem ve bedel der; Süheylî bedeli ve atf-ı beyanı reddeder, çünkü 'Rahmân nedir' denmiş 'Allah nedir' denmemiştir (25:60).", "iddia": ["I53"], "iliski": "genisletme"}
{"seg": "ABUHAYYAN:1:1", "konu": "Rahmân/Rahîm farkı ve görüşler", "tur": "tefsir_rivayet", "alim": "Mücâhid; İbn Mes'ûd ve Ebû Saîd el-Hudrî (merfû); el-Kurtubî; ed-Dahhâk; İkrime", "alinti": "فقال مجاهد : رحمن الدنيا ورحيم الآخرة .", "ozet": "Mücâhid: dünya Rahmânı, ahiret Rahîmi; İbn Mes'ûd ve Ebû Saîd merfû aktarır; Kurtubî tersini; Dahhâk, İkrime, Müznî, Ezîzî, Muhâsibî, Yahyâ b. Muâz, Sâdık, Sa'leb ve Fârisî farklı ayrımlar yapar.", "iddia": ["I50", "I52"], "iliski": "genisletme", "derece": "merfû rivayet, Ebû Hayyân 'sahihse' der"}
{"seg": "ABUHAYYAN:1:1", "konu": "rahmet sıfat-ı fiil mi zât mı", "tur": "kelam", "alim": "Ebû Alî el-Fârisî; bir topluluk", "alinti": "ووصف الله تعالى بالرحمة مجاز عن إنعامه على عباده", "ozet": "Rahmet nimetten mecazdır, sıfat-ı fiildir; bir grup hayır iradesi der, sıfat-ı zâttır; bundan fiil sıfatlarının ezeliliği tartışması doğar.", "iddia": ["I58"], "iliski": "genisletme"}
{"seg": "ABUHAYYAN:1:1", "konu": "besmelede belâgat: hazf ve tekrar", "tur": "belagat", "alim": "es-Süheylî; Ebû Hayyân", "alinti": "وذلك أنه موطن ينبغي أن لا يقدم فيه سوى ذكر الله تعالى", "ozet": "Hazf, Süheylî'ye göre sadece hafiflik için değil: orada Allah'ın zikrinden başkası öne alınmamalıdır; ikinci nevi sıfatta tekrar, ta'zîm veya te'kid içindir.", "iddia": ["I2"], "iliski": "destek"}
{"seg": "ABUHAYYAN:1:1", "konu": "Rahîm'in Hamd'e vaslı", "tur": "kiraat", "alim": "Kûfeliler; el-Kisâî", "alinti": "والجمهور على جر الميم ووصل الألف من الحمد", "ozet": "Kûfelilerden bir grup mîm'i sakin okur ve hemze-i kat' ile başlar; cumhur kesre ile vasleder; Kisâî'nin hikâyesi ayrıca.", "iddia": [], "iliski": "yeni"}
{"seg": "ABUHAYYAN-FULL:v1p27", "konu": "bâ'nın anlamları ve ilk bilgiler", "tur": "nahiv", "alim": "Ebû Hayyân", "alinti": "باء الجر تأتي لمعان: للإلصاق، والاستعانة، والقسم، والسبب، والحال، والظرفية، والنقل.", "ozet": "Cer bâ'sının anlamları sayılır; ism'in lugatları ve Basra-Kûfe türemesi; elin türleri ve Allah'ın mürtecel oluşu.", "iddia": ["I1", "I13"], "iliski": "genisletme"}
{"seg": "ABUHAYYAN-FULL:v1p28", "konu": "Allah ismi türemeleri", "tur": "lugat", "alim": "İbn İshâk; Ebû Amr; en-Nadr; el-Müberred; el-Halîl", "alinti": "وقيل: لام وواو وهاء من لاه يلوه لوها، احتجب أو استتار", "ozet": "Allah'ın kökleri: lâhe yelîhi (yükseldi), lâhe yelûhu (gizlendi), ilâh (feza, hayret, ibadet, sükûn), vele (Halîl); el için gâlebe, zâid-i lâzım ve es-Süheylî-İbnü'l-Arabî eli aslî sayar.", "iddia": ["I37", "I46"], "iliski": "destek"}
{"seg": "ABUHAYYAN-FULL:v1p28", "konu": "Allah ismi garip görüşler", "tur": "lugat", "alim": "Ebû Yezîd el-Belhî", "alinti": "قال أبو يزيد البلخي: هو أعجمي، فإن اليهود والنصارى يقولون لاها", "ozet": "Belhî: Allah ismi yabancıdır; ayrıca sıfat olduğu görüşü ve son elifin yazıdan düşme sebepleri.", "iddia": ["I37"], "iliski": "yeni"}
{"seg": "ABUHAYYAN-FULL:v1p28#2", "konu": "الرحمن lugatı", "tur": "nahiv", "alim": "Ebû Hayyân; Sa'leb", "alinti": "الرحمن: فعلان من الرحمة، وأصل بنائه من اللازم من المبالغة وشذ من", "ozet": "Rahmân rahmetten fa'lân; el gâlebe içindir; Allah'tan başkasında kullanılmaz, kullananlar mülhidlerin inadıdır; Sa'leb hâ ile yabancı der.", "iddia": ["I49", "I52"], "iliski": "destek"}
{"seg": "ABUHAYYAN-FULL:v1p28#2", "konu": "الرحيم vezni ve rahîm=merhûm", "tur": "nahiv", "alim": "Ebû Hayyân; el-Amelles b. Akîl", "alinti": "الرحيم: فعيل محول من فاعل للمبالغة، وهو أحد الأمثلة الخمسة", "ozet": "Rahîm, fâilden mübalağa için çevrilmiş fe'îl kalıbıdır; bazen merhûm anlamında gelir, beyit şahit.", "iddia": ["I50"], "iliski": "destek"}
{"seg": "ABUHAYYAN-FULL:v1p28#2", "konu": "bâ müteallakı ve Fâtiha'nın nüzulü", "tur": "nuzul", "alim": "Ali, İbn Abbâs, Katâde ve diğerleri; Ebû Hüreyre ve diğerleri", "alinti": "هي مدنية، وقيل إنها مكية مدنية.", "ozet": "Mekkî diyenler ve medenî diyenler sayılır; ayrıca bâ'nın istiâne olduğu ve Kûfelilere göre mahallinin nasb olduğu tekrarlanır.", "iddia": [], "iliski": "yeni"}
{"seg": "ABUHAYYAN-FULL:v1p30", "konu": "isim-müsemmâ-tesmiye", "tur": "kelam", "alim": "Ebû Hayyân; es-Süheylî", "alinti": "والاسم هو اللفظ الدال بالوضع على موجود في العيان، إن كان محسوسا", "ozet": "İsim, müsemmâ ve tesmiye ayrıdır; isim bazen mecazen müsemmâ anlamında kullanılır; Gazâlî, İbnü's-Seyyid, Süheylî tartışmayı uzatmıştır.", "iddia": ["I19"], "iliski": "genisletme"}
{"seg": "ABUHAYYAN-FULL:v1p30", "konu": "'sebbih isme rabbike' te'vili", "tur": "belagat", "alim": "es-Süheylî", "alinti": "لأن الذكر بالقلب متعلقه المسمى المدلول عليه بالاسم، والذكر باللسان متعلقه اللفظ.", "ozet": "'İsm' tembih için eklenmiş; kalp zikri müsemmâya, dil zikri lafza bağlıdır; 'isimlerden başka bir şey değil' sahte isimlerdir ve güzel mecazdır.", "iddia": ["I18", "I28"], "iliski": "destek"}
{"seg": "ABUHAYYAN-FULL:v1p30", "konu": "Rahmân bedel mi sıfat mı", "tur": "nahiv", "alim": "el-A'lem", "alinti": "والرحمن صفة الله عند الجماعة. وذهب الأعلم وغيره إلى أنه بدل", "ozet": "Cemaate göre sıfat; A'lem'e göre bedel, çünkü Rahmân alemdir ve tâbi olmadan gelir (20:5, 55:1).", "iddia": ["I52"], "iliski": "genisletme"}
{"seg": "ABUHAYYAN-FULL:v1p31", "konu": "Rahmân ve Rahîm: bir mi farklı mı", "tur": "belagat", "alim": "ez-Zemahşerî; Ebû Hayyân", "alinti": "فمبالغة فعلان مثل غضبان وسكران من حيث الامتلاء والغلبة، ومبالغة فعيل من حيث التكرار والوقوع بمحال الرحمة", "ozet": "Aynı anlam (nedmân/nedîm) veya farklı: Rahmân daha beliğ (Zemahşerî), Rahîm daha beliğ; Ebû Hayyân'a göre mübalağa yönleri farklıdır, bu yüzden te'kid değildir.", "iddia": ["I49", "I50"], "iliski": "destek"}
{"seg": "ABUHAYYAN-FULL:v1p31", "konu": "dünya Rahmânı hadisi", "tur": "hadis", "alim": "İbn Mes'ûd ve Ebû Saîd el-Hudrî (Peygamber'den)", "alinti": "«الرحمن رحمن الدنيا والرحيم رحيم الآخرة»", "ozet": "İbn Mes'ûd ve Ebû Saîd: Rahmân dünyanın Rahmânı, Rahîm ahiretin Rahîmi; sahihse bu tefsire gidilmelidir.", "iddia": ["I50"], "iliski": "genisletme", "derece": "sahih=belirsiz (Ebû Hayyân 'sahihse' der)"}
{"seg": "ABUHAYYAN-FULL:v1p31", "konu": "Rahmân Rahîm ayrımları", "tur": "tefsir_dirayet", "alim": "Mücâhid, Dahhâk, İkrime, Müznî, Ezîzî, Muhâsibî, Yahyâ b. Muâz, Sâdık, Sa'leb, Fârisî", "alinti": "وقال أبو علي الفارسي: الرحمن اسم عام في جميع أنواع الرحمة، يختص به الله، والرحيم إنما هو في جهة المؤمنين", "ozet": "Fârisî: Rahmân tüm rahmet türlerinde genel ve Allah'a özgü, Rahîm müminlere yönelik; Sa'leb: Rahmân daha övücü, Rahîm daha lâtif.", "iddia": ["I50", "I52"], "iliski": "genisletme"}
{"seg": "ABUHAYYAN-FULL:v1p31#2", "konu": "rahmet: irade mi ihsan mı", "tur": "kelam", "alim": "bir topluluk", "alinti": "هي إرادة الخير لمن أراد الله تعالى به ذلك، فتكون على هذا صفة ذات", "ozet": "Rahmet hayır iradesidir, sıfat-ı zâttır; bundan zât ve fiil sıfatlarının kıdemi tartışması doğar; kul rahmeti kalpte incelik veya hayır kastıdır.", "iddia": ["I58"], "iliski": "genisletme"}
{"seg": "ABUHAYYAN-FULL:v1p31#2", "konu": "besmelede iki belâgat nevi", "tur": "belagat", "alim": "Ebû Hayyân; es-Süheylî", "alinti": "وفي البسملة من ضروب البلاغة نوعان:", "ozet": "Biri hazf (müteallak), ikincisi sıfatta tekrar (ta'zîm veya te'kid); Süheylî'ye göre fiil, zikrullahın öne geçmesi için düşürülmüştür.", "iddia": ["I2"], "iliski": "destek"}
{"seg": "ABUHAYYAN-FULL:v1p31#2", "konu": "Rahîm'in Hamd'e vaslı", "tur": "kiraat", "alim": "Kûfeliler; el-Kisâî", "alinti": "واختلف في وصل الرحيم بالحمد، فقرأ قوم من الكوفيين بسكون الميم", "ozet": "Bir grup Kûfeli mîm'i sakin okur ve hemze-i kat' ile başlar; cumhur kesreyle vasleder; Kisâî'nin hikâyesi tekrarlanır.", "iddia": [], "iliski": "yeni"}
{"seg": "ABUHAYYAN-FULL:v1p32", "bos": true, "neden": "yalnız Hamd ve rabbü'l-âlemîn"}
{"seg": "ABUHAYYAN-FULL:v1p34", "bos": true, "neden": "Hamd kıraatleri, besmele yok"}
{"seg": "ABUHAYYAN-FULL:v1p35", "konu": "Rahmân Rahîm'in 1:3'teki tekrarı", "tur": "nazm", "alim": "Mekkî; Ebû Hayyân", "alinti": "وفي تكرار الرحمن الرحيم إن كانت التسمية آية من الفاتحة تنبيه على عظم قدر هاتين الصفتين وتأكيد أمرهما", "ozet": "Besmele Fâtiha'dan ayetse tekrar iki sıfatın büyüklüğüne tembihtir; Mekkî tekrarı besmelenin ayet olmadığına delil sayar, Ebû Hayyân reddeder.", "iddia": ["I55"], "iliski": "destek"}
{"seg": "ABUHAYYAN-FULL:v1p35", "konu": "Rahmân Rahîm Rab sıfatları", "tur": "belagat", "alim": "Ebû Hayyân", "alinti": "فناسب ذلك الوصف بالرحمانية والرحيمية، لينبسط أمل العبد في العفو إن زل", "ozet": "Rab olmanın ardından rahmet sıfatları gelir ki kulun affa umudu genişlesin; Rahmân ve Rahîm hem müsellem hem sıfat-ı medihtir.", "iddia": ["I55"], "iliski": "genisletme"}
{"seg": "ABUHAYYAN-FULL:v1p36", "bos": true, "neden": "vakıf ve mâlik kıraatleri"}
{"seg": "ABUHAYYAN-FULL:v1p37", "bos": true, "neden": "mâlik/melik ve din, besmele yok"}
{"seg": "ABUHAYYAN-FULL:v1p38", "bos": true, "neden": "din ve mâlik i'râbı"}
{"seg": "ABUHAYYAN-FULL:v1p39", "bos": true, "neden": "mâlik/melik tercihi"}
{"seg": "ABUHAYYAN-FULL:v1p40", "konu": "Rahmân Rahîm: genel ve hâs", "tur": "belagat", "alim": "Ebû Alî el-Fârisî", "alinti": "ومنه الرحمن الرحيم، ذكر الرحمن الذي هو عام، وذكر الرحيم بعده لتخصيص الرحمة بالمؤمنين", "ozet": "Önce genel, sonra özel anılır: Rahmân genel, Rahîm ardından rahmeti müminlere has kılar (33:43).", "iddia": ["I50"], "iliski": "destek"}
{"seg": "ABUHAYYAN-FULL:v1p40#2", "bos": true, "neden": "iyyâke ve nasta'în"}
{"seg": "ABUHAYYAN-FULL:v1p42", "bos": true, "neden": "iyyâke nasta'în, iltifat"}
{"seg": "ABUHAYYAN-FULL:v1p43", "bos": true, "neden": "iltifat ve iyyâke"}
{"seg": "ABUHAYYAN-FULL:v1p43#2", "bos": true, "neden": "iyyâke na'budü, ibadet"}
